import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { api } from '../utils/api';
import { CYCLES_DILIGENCES, DOCUMENTS_REQUIS } from '../utils/diligencesData';

const AppContext = createContext(null);

// Admin sits above expert — same permissions plus a few override-only actions (e.g.
// unlocking a note PDC already generated by IA). Single source of truth for role level,
// imported wherever a component previously redefined its own ROLES_NIVEAU constant.
const ROLES = {
  admin: { label: 'Administrateur', niveau: 4, couleur: '#7c3aed' },
  expert: { label: 'Expert-Comptable', niveau: 3, couleur: '#1a3a5c' },
  senior: { label: 'Collaborateur Senior', niveau: 2, couleur: '#2563a8' },
  assistant: { label: 'Assistant / Stagiaire', niveau: 1, couleur: '#5b8dd9' },
};

export const ROLES_NIVEAU = { admin: 4, expert: 3, senior: 2, assistant: 1 };

const ETAPES = [
  { id: 1, cle: 'prise_de_connaissance', label: 'Prise de connaissance', icone: 'Search', roleMin: 'assistant' },
  { id: 2, cle: 'lettre_de_mission', label: 'Lettre de mission', icone: 'FileText', roleMin: 'senior' },
  { id: 3, cle: 'demande_documents', label: 'Demande de documents', icone: 'FolderOpen', roleMin: 'assistant' },
  { id: 4, cle: 'diligences', label: 'Diligences', icone: 'ClipboardCheck', roleMin: 'assistant' },
  { id: 5, cle: 'note_synthese', label: 'Note de synthèse', icone: 'BookOpen', roleMin: 'senior' },
  { id: 6, cle: 'bouclage', label: 'Bouclage', icone: 'Lock', roleMin: 'expert' },
  { id: 7, cle: 'attestation', label: 'Attestation / Refus', icone: 'Award', roleMin: 'expert' },
];

const STATUTS = {
  non_commence: { label: 'Non commencé', couleur: '#9ca3af' },
  en_cours: { label: 'En cours', couleur: '#f59e0b' },
  complete: { label: 'Complété', couleur: '#10b981' },
  valide: { label: 'Validé', couleur: '#1a3a5c' },
};

export function AppProvider({ children }) {
  const [utilisateurConnecte, setUtilisateurConnecte] = useState(() => {
    const saved = localStorage.getItem('fidea_user');
    return saved ? JSON.parse(saved) : null;
  });
  const [dossiers, setDossiers] = useState([]);
  const [utilisateurs, setUtilisateurs] = useState([]);
  const [chargement, setChargement] = useState(false);
  const [erreurConnexion, setErreurConnexion] = useState(false);
  const [sauvegarde, setSauvegarde] = useState(false);

  // Load initial data when user is connected
  useEffect(() => {
    if (utilisateurConnecte) {
      chargerDonnees();
    }
  }, [utilisateurConnecte]);

  const chargerDonnees = async () => {
    try {
      const [dossiersData, utilisateursData] = await Promise.all([
        api.getDossiers(),
        api.getUtilisateurs(),
      ]);
      setDossiers(dossiersData);
      setUtilisateurs(utilisateursData);
      setErreurConnexion(false);
    } catch (err) {
      console.error('Erreur chargement données:', err);
      setErreurConnexion(true);
    }
  };

  // Auto-logout on persistent 401
  useEffect(() => {
    const handleUnauthorized = () => {
      deconnexion();
    };
    window.addEventListener('fidea_unauthorized', handleUnauthorized);
    return () => window.removeEventListener('fidea_unauthorized', handleUnauthorized);
  }, []);

  const connexion = async (email, motDePasse) => {
    try {
      setChargement(true);
      const { token, utilisateur } = await api.connexion(email, motDePasse);
      localStorage.setItem('fidea_token', token);
      localStorage.setItem('fidea_user', JSON.stringify(utilisateur));
      setUtilisateurConnecte(utilisateur);
      return { succes: true };
    } catch (err) {
      return { succes: false, erreur: err.message };
    } finally {
      setChargement(false);
    }
  };

  const deconnexion = () => {
    setUtilisateurConnecte(null);
    setDossiers([]);
    setUtilisateurs([]);
    localStorage.removeItem('fidea_token');
    localStorage.removeItem('fidea_user');
  };

  const creerDossier = async (donnees) => {
    try {
      const nouveau = await api.creerDossier(donnees);
      setDossiers(prev => [nouveau, ...prev]);
      return nouveau;
    } catch (err) {
      console.error(err);
      throw err;
    }
  };

  const dupliquerDossier = async (dossierSource, nouvelExercice) => {
    try {
      const donnees = {
        nomEntite: dossierSource.nomEntite,
        nccEntite: dossierSource.nccEntite,
        adresseEntite: dossierSource.adresseEntite || '',
        exercice: nouvelExercice,
        nomGerant: dossierSource.nomGerant || '',
        chiffreAffaires: dossierSource.chiffreAffaires || '',
        totalBilan: dossierSource.totalBilan || '',
        capitauxPropres: dossierSource.capitauxPropres || '',
        resultatNet: dossierSource.resultatNet || '',
        totalProduits: dossierSource.totalProduits || '',
        montantHonoraires: dossierSource.montantHonoraires || '',
        nombreHeures: dossierSource.nombreHeures || '',
        nomAssistant: dossierSource.nomAssistant || '',
      };
      const nouveau = await api.creerDossier(donnees);
      setDossiers(prev => [nouveau, ...prev]);
      return nouveau;
    } catch (err) {
      console.error(err);
      throw err;
    }
  };

  const ajouterHistorique = useCallback((dossierId, action) => {
    setDossiers(prev => prev.map(d => {
      if (d.id !== dossierId) return d;
      const historique = [...(d.historique || []), {
        action,
        auteur: utilisateurConnecte?.nom || 'Inconnu',
        date: new Date().toISOString(),
      }].slice(-50); // garder les 50 dernières actions
      const dossierMaj = { ...d, historique };
      api.mettreAJourDossier(dossierId, dossierMaj).catch(console.error);
      return dossierMaj;
    }));
  }, [utilisateurConnecte]);

  // Appends one entry to a dossier's historique in-memory (used by updaters below so the
  // log write rides along with their own single api.mettreAJourDossier call, instead of
  // firing a second network request via ajouterHistorique).
  const appendHistorique = (dossier, action) => {
    const historique = [...(dossier.historique || []), {
      action,
      auteur: utilisateurConnecte?.nom || 'Inconnu',
      date: new Date().toISOString(),
    }].slice(-50);
    return { ...dossier, historique };
  };

  // Central update function — merges local state and persists to server.
  // Builds the PUT payload from the functional-update callback's own `d` (the latest
  // pending state), not from the outer `dossiers` closure — two calls fired close together
  // (e.g. saving the PDC note right after a debounced autosave elsewhere) would otherwise
  // race: the one built from the older snapshot can land second on the server and silently
  // revert whatever the other one just wrote.
  const mettreAJourDossierComplet = useCallback(async (dossierId, miseAJour) => {
    let dossierMaj = null;
    setDossiers(prev => prev.map(d => {
      if (d.id !== dossierId) return d;
      dossierMaj = { ...d, ...miseAJour };
      return dossierMaj;
    }));
    setSauvegarde(true);
    try {
      if (!dossierMaj) return;
      await api.mettreAJourDossier(dossierId, dossierMaj);
    } catch (err) {
      console.error('Erreur sauvegarde dossier:', err);
      chargerDonnees();
    } finally {
      setTimeout(() => setSauvegarde(false), 1500);
    }
  }, []);

  const mettreAJourEtape = useCallback((dossierId, etapeCle, donnees) => {
    setDossiers(prev => prev.map(d => {
      if (d.id !== dossierId) return d;
      const etapesMaj = {
        ...d.etapes,
        [etapeCle]: { ...d.etapes[etapeCle], ...donnees }
      };
      let etapeActuelle = 1;
      for (let i = 0; i < ETAPES.length; i++) {
        const e = ETAPES[i];
        if (['complete', 'valide'].includes(etapesMaj[e.cle]?.statut)) {
          etapeActuelle = Math.min(i + 2, ETAPES.length);
        }
      }
      const dossierMaj = { ...d, etapes: etapesMaj, etapeActuelle };
      // Persist async
      api.mettreAJourDossier(dossierId, dossierMaj).catch(console.error);
      return dossierMaj;
    }));
  }, []);

  const mettreAJourDocument = useCallback((dossierId, docId, statut) => {
    setDossiers(prev => prev.map(d => {
      if (d.id !== dossierId) return d;
      const documentsRecus = { ...(d.documentsRecus || {}), [docId]: statut };
      let dossierMaj = { ...d, documentsRecus };
      if (statut === 'ok') {
        const docNom = DOCUMENTS_REQUIS.find(doc => doc.id === docId)?.nom
          || (d.documentsRequisPersonnalises || []).find(doc => doc.id === docId)?.nom
          || docId;
        dossierMaj = appendHistorique(dossierMaj, `Document reçu : "${docNom}"`);
      }
      api.mettreAJourDossier(dossierId, dossierMaj).catch(console.error);
      return dossierMaj;
    }));
  }, [utilisateurConnecte]);

  // Liste indicative de documents — extension par dossier, saisie depuis l'étape
  // "Demande de documents" (au-delà de la liste standard DOCUMENTS_REQUIS).
  const ajouterDocumentPersonnalise = useCallback((dossierId, nom) => {
    setDossiers(prev => prev.map(d => {
      if (d.id !== dossierId) return d;
      const nouveauDoc = { id: `custom_${Date.now()}`, nom };
      const documentsRequisPersonnalises = [...(d.documentsRequisPersonnalises || []), nouveauDoc];
      let dossierMaj = { ...d, documentsRequisPersonnalises };
      dossierMaj = appendHistorique(dossierMaj, `Document ajouté à la liste : "${nom}"`);
      api.mettreAJourDossier(dossierId, dossierMaj).catch(console.error);
      return dossierMaj;
    }));
  }, [utilisateurConnecte]);

  const retirerDocumentPersonnalise = useCallback((dossierId, docId) => {
    setDossiers(prev => prev.map(d => {
      if (d.id !== dossierId) return d;
      const doc = (d.documentsRequisPersonnalises || []).find(doc => doc.id === docId);
      const documentsRequisPersonnalises = (d.documentsRequisPersonnalises || []).filter(doc => doc.id !== docId);
      const documentsRecus = { ...(d.documentsRecus || {}) };
      delete documentsRecus[docId];
      let dossierMaj = { ...d, documentsRequisPersonnalises, documentsRecus };
      if (doc) dossierMaj = appendHistorique(dossierMaj, `Document retiré de la liste : "${doc.nom}"`);
      api.mettreAJourDossier(dossierId, dossierMaj).catch(console.error);
      return dossierMaj;
    }));
  }, [utilisateurConnecte]);

  const assignerCycle = useCallback((dossierId, cycleId, userId) => {
    setDossiers(prev => prev.map(d => {
      if (d.id !== dossierId) return d;
      const cyclesAssignations = { ...(d.cyclesAssignations || {}), [cycleId]: userId };
      const dossierMaj = { ...d, cyclesAssignations };
      api.mettreAJourDossier(dossierId, dossierMaj).catch(console.error);
      return dossierMaj;
    }));
  }, []);

  const mettreAJourReponse = useCallback((dossierId, cycleId, pointId, reponse) => {
    setDossiers(prev => prev.map(d => {
      if (d.id !== dossierId) return d;
      const cyclesReponses = d.cyclesReponses || {};
      const cycleData = cyclesReponses[cycleId] || {};
      const points = cycleData.points || {};
      const dossierMaj = {
        ...d,
        cyclesReponses: {
          ...cyclesReponses,
          [cycleId]: { ...cycleData, points: { ...points, [pointId]: { ...(points[pointId] || {}), ...reponse } } }
        }
      };
      api.mettreAJourDossier(dossierId, dossierMaj).catch(console.error);
      return dossierMaj;
    }));
  }, []);

  const signerCycleFait = useCallback((dossierId, cycleId, userId) => {
    const cycleLabel = CYCLES_DILIGENCES.find(c => c.id === cycleId)?.label || cycleId;
    setDossiers(prev => prev.map(d => {
      if (d.id !== dossierId) return d;
      const cyclesReponses = d.cyclesReponses || {};
      const cycleData = cyclesReponses[cycleId] || {};
      let dossierMaj = {
        ...d,
        cyclesReponses: { ...cyclesReponses, [cycleId]: { ...cycleData, faitPar: userId, dateFait: new Date().toISOString() } }
      };
      dossierMaj = appendHistorique(dossierMaj, `Cycle "${cycleLabel}" signé (fait)`);
      api.mettreAJourDossier(dossierId, dossierMaj).catch(console.error);
      return dossierMaj;
    }));
  }, [utilisateurConnecte]);

  const signerCycleSupervise = useCallback((dossierId, cycleId, userId) => {
    const cycleLabel = CYCLES_DILIGENCES.find(c => c.id === cycleId)?.label || cycleId;
    setDossiers(prev => prev.map(d => {
      if (d.id !== dossierId) return d;
      const cyclesReponses = d.cyclesReponses || {};
      const cycleData = cyclesReponses[cycleId] || {};
      let dossierMaj = {
        ...d,
        cyclesReponses: { ...cyclesReponses, [cycleId]: { ...cycleData, supervise: userId, dateSupervise: new Date().toISOString() } }
      };
      dossierMaj = appendHistorique(dossierMaj, `Cycle "${cycleLabel}" supervisé`);
      api.mettreAJourDossier(dossierId, dossierMaj).catch(console.error);
      return dossierMaj;
    }));
  }, [utilisateurConnecte]);

  const ajouterCollaborateur = useCallback(async (dossierId, userId) => {
    try {
      const updated = await api.ajouterCollaborateur(dossierId, userId);
      setDossiers(prev => prev.map(d => d.id === dossierId ? updated : d));
      const nom = utilisateurs.find(u => u.id === userId)?.nom || 'Collaborateur';
      ajouterHistorique(dossierId, `${nom} ajouté à l'équipe`);
    } catch (err) {
      console.error(err);
    }
  }, [utilisateurs, ajouterHistorique]);

  const retirerCollaborateur = useCallback(async (dossierId, userId) => {
    try {
      const updated = await api.retirerCollaborateur(dossierId, userId);
      setDossiers(prev => prev.map(d => d.id === dossierId ? updated : d));
      const nom = utilisateurs.find(u => u.id === userId)?.nom || 'Collaborateur';
      ajouterHistorique(dossierId, `${nom} retiré de l'équipe`);
    } catch (err) {
      console.error(err);
    }
  }, [utilisateurs, ajouterHistorique]);

  const creerUtilisateur = async (data) => {
    const nouveau = await api.creerUtilisateur(data);
    setUtilisateurs(prev => [...prev, nouveau]);
    return nouveau;
  };

  const modifierUtilisateur = async (id, data) => {
    const updated = await api.modifierUtilisateur(id, data);
    setUtilisateurs(prev => prev.map(u => u.id === id ? updated : u));
    return updated;
  };

  const supprimerUtilisateur = async (id) => {
    await api.supprimerUtilisateur(id);
    setUtilisateurs(prev => prev.filter(u => u.id !== id));
  };

  const peutAccederEtape = (etapeCle, roleUtilisateur) => {
    const etape = ETAPES.find(e => e.cle === etapeCle);
    if (!etape) return false;
    return ROLES[roleUtilisateur]?.niveau >= ROLES[etape.roleMin]?.niveau;
  };

  return (
    <AppContext.Provider value={{
      utilisateurConnecte,
      dossiers,
      utilisateurs,
      chargement,
      sauvegarde,
      erreurConnexion,
      ROLES,
      ETAPES,
      STATUTS,
      connexion,
      deconnexion,
      chargerDonnees,
      creerDossier,
      dupliquerDossier,
      ajouterHistorique,
      mettreAJourEtape,
      mettreAJourDossierComplet,
      mettreAJourDocument,
      ajouterDocumentPersonnalise,
      retirerDocumentPersonnalise,
      assignerCycle,
      mettreAJourReponse,
      signerCycleFait,
      signerCycleSupervise,
      ajouterCollaborateur,
      retirerCollaborateur,
      creerUtilisateur,
      modifierUtilisateur,
      supprimerUtilisateur,
      peutAccederEtape,
    }}>
      {children}
    </AppContext.Provider>
  );
}

export const useApp = () => useContext(AppContext);
